def rows(n):
    u=C['sheets'].get(n,'')
    try: t=urllib.request.urlopen(u,timeout=20).read().decode('utf-8') if u else open('data/%s.csv'%n,encoding='utf-8').read()
    except Exception: t=open('data/%s.csv'%n,encoding='utf-8').read()
    return [r for r in csv.DictReader(io.StringIO(t)) if any((v or '').strip() for v in r.values())]
