def page(path,title,desc,body,extra=''):
    h=_page(path,title,desc,body,extra)
    h=h.replace('<link rel="stylesheet" href="/assets/style.css">','<style>'+CSS+'</style>').replace('<script src="/assets/app.js" defer></script>','<script>'+JS+'</script>').replace('/assets/logo-icon.png',ICON).replace('<meta charset="utf-8">','<meta charset="utf-8"><!-- avis-build:v5-font -->',1)
    if path.startswith('/404'): return h
    pre='./' if path=='/' else '../../'
    return re.sub(r'(href|src)="/(?!/)',lambda m:m.group(1)+'="'+pre,h)
def _page(path,title,desc,body,extra=''):
    return '<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>%s</title><meta name="description" content="%s"><link rel="canonical" href="%s%s"><meta property="og:title" content="%s"><meta property="og:description" content="%s"><meta property="og:type" content="website"><meta property="og:url" content="%s%s"><meta property="og:image" content="%s/assets/logo.png"><meta name="theme-color" content="#04a0b5"><link rel="icon" href="/assets/favicon.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/style.css">%s</head><body>%s%s%s%s<script>const WA="%s"</script><script src="/assets/app.js" defer></script></body></html>'%(e(title),e(desc),D,path,e(title),e(desc),D,path,D,extra,HEADER,body,FOOTER,FAB,WA)
